import React from 'react';
import { useNavigate } from 'react-router-dom'; // Import useNavigate
import Header from './Header';
import Footer from './Footer';
import './Thankyou.css';  // Make sure you have your CSS file imported
import saree from './saree1.jpg';  // Ensure the image file path is correct

const Thankyou = () => {
    const navigate = useNavigate(); // Initialize useNavigate

    // Handle the Go back Home button click
    const onButtonClick = () => {
        navigate('/HomePage'); // Navigate to HomePage
    };

    return (
        <div>
            <Header />
            <div className="mainContainer">
                <div id="app">
                    <div className="title">
                        <div className="title-inner">
                            <div className="cafe">
                                <div className="cafe-inner">Keyframé</div>
                            </div>
                            <div className="mozart">
                                <div className="mozart-inner">Artistes</div>
                            </div>
                        </div>
                    </div>

                    <div className="image">
                        <img src={saree} alt="Saree" />
                    </div>

                    <div className="thankyou-message">
                        <h1>Thank you for shopping with us!</h1>
                        <p>We appreciate your purchase and hope to see you again soon. If you have any questions, feel free to contact our support team.</p>
                        <button className="homeButton" onClick={onButtonClick}>Go back Home</button>
                    </div>
                </div>
            </div>
            <Footer />
        </div>
    );
};

export default Thankyou;
